script:
export const meta = {
  name: 'pi_sessions_optimization',
  description: 'Analyze pi session corpus evidence; produce ranked, confidence-scored optimizations for the harness and our usage of it.',
  phases: [
    { title: 'Specialist analysis' },
    { title: 'Synthesis and ranking' }
  ]
};

const evidence = args.evidence;

const recSchema = {
  type: 'object',
  required: ['recommendations'],
  properties: {
    perspective: { type: 'string' },
    recommendations: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'title', 'category', 'description', 'evidence', 'confidence', 'impact', 'effort', 'risk'],
        properties: {
          id: { type: 'string' },
          title: { type: 'string' },
          category: { type: 'string', description: 'harness | usage | prompt | tooling | model-routing | observability' },
          description: { type: 'string' },
          evidence: { type: 'string', description: 'Specific numbers/clusters from the pack supporting this' },
          confidence: { type: 'number', description: '0..1 — how strongly the data supports this recommendation' },
          confidenceRationale: { type: 'string' },
          impact: { type: 'string', description: 'low | medium | high — estimated $ / time / quality impact' },
          effort: { type: 'string', description: 'low | medium | high' },
          risk: { type: 'string', description: 'side-effects, regressions, or known counter-arguments' },
          concreteAction: { type: 'string', description: 'What to actually change (file, prompt edit, tool flag, etc.)' }
        }
      }
    }
  }
};

phase('Specialist analysis');

const briefBase = `You are reviewing aggregated evidence from 385 pi (coding agent) sessions. Goal: produce optimization recommendations from your specialist angle. Be concrete. Cite the numbers. Do not invent data beyond the evidence. Return 3-6 high-signal recommendations, each with a confidence score (0..1) reflecting how strongly the evidence supports it.

EVIDENCE PACK:
${evidence}

Output JSON matching the provided schema. confidence rubric:
  0.9-1.0 = multiple converging signals, large N, mechanism clear
  0.7-0.9 = clear single signal with believable mechanism
  0.5-0.7 = directional signal, mechanism plausible, more data would help
  <0.5 = speculative

Your specialist focus:`;

const specialists = [
  { label: 'cost analyst', focus: 'Cost & token economics: where is $1,951 burning, which sessions/tools dominate, what tiering/context-pruning/model-selection changes would cut spend most.', tier: 'medium' },
  { label: 'orchestration gap', focus: 'Subagent / workflow / async-parallel adoption gap. Why is workflow=0, subagent at 18% of sessions, async at 11%, when AGENTS.md mandates async-parallel default and >0.30 ratio? Prompt design changes, tool affordances, friction.', tier: 'medium' },
  { label: 'parallel batching', focus: 'The 0.127 parallel/serial ratio. System prompt explicitly demands batching independents. Why is the model not batching? Prompt placement, planning prompts, examples, harness affordances.', tier: 'medium' },
  { label: 'tool-error clusters', focus: 'Error clusters: bash sudo TTY loops, edit oldText anchors, ctx_* disk-I/O + outdated version, MCP timeouts, ask_user_question schema, chrome extension flakiness. Which are harness bugs vs usage bugs.', tier: 'medium' },
  { label: 'long-session pathology', focus: 'Long/expensive sessions (p99 258 tc, max 414). Duplicate-arg replays (537 corpus-wide), failed-retry loops (681). What harness signals / circuit breakers / forced-summarization mechanics could short-circuit waste.', tier: 'medium' },
  { label: 'standing orders fidelity', focus: 'AGENTS.md is symlinked everywhere yet floor ratios are missed 10x. Goal-loop GOAL-STALE bouncing within turns. Are standing orders the wrong shape, the wrong delivery mechanism, or simply ignored under tempo pressure?', tier: 'medium' }
];

const findings = await parallel(specialists.map(s => () => agent(
  `${briefBase} ${s.focus}\n\nReturn JSON: { perspective: '${s.label}', recommendations: [...] }.`,
  { label: s.label, tier: s.tier, schema: recSchema }
)));

const validFindings = findings.filter(f => f && Array.isArray(f.recommendations));
log(`Specialist findings: ${validFindings.length}/${specialists.length} returned; total recs = ${validFindings.reduce((n,f)=>n+f.recommendations.length,0)}`);

phase('Synthesis and ranking');

const synthSchema = {
  type: 'object',
  required: ['headline', 'topRecommendations', 'secondTier', 'rejectedOrDuplicate', 'metaNotes'],
  properties: {
    headline: { type: 'string', description: '3-5 sentence executive summary of what is wrong and what to do.' },
    topRecommendations: {
      type: 'array',
      description: '8-12 ranked recommendations. Merge duplicates across specialists. Rank by impact*confidence/effort.',
      items: {
        type: 'object',
        required: ['rank', 'id', 'title', 'category', 'audience', 'description', 'evidence', 'confidence', 'impact', 'effort', 'risk', 'concreteAction', 'expectedOutcome'],
        properties: {
          rank: { type: 'number' },
          id: { type: 'string' },
          title: { type: 'string' },
          category: { type: 'string' },
          audience: { type: 'string', description: 'harness-author (pi maintainer) | user (Anish) | both' },
          description: { type: 'string' },
          evidence: { type: 'string' },
          confidence: { type: 'number' },
          confidenceRationale: { type: 'string' },
          impact: { type: 'string' },
          effort: { type: 'string' },
          risk: { type: 'string' },
          concreteAction: { type: 'string' },
          expectedOutcome: { type: 'string', description: 'Quantified if possible — e.g. % cost reduction, % error reduction.' }
        }
      }
    },
    secondTier: {
      type: 'array',
      items: { type: 'object', required: ['title','confidence','reason'], properties: { title:{type:'string'}, confidence:{type:'number'}, reason:{type:'string'} } }
    },
    rejectedOrDuplicate: {
      type: 'array',
      items: { type: 'object', required: ['title','reason'], properties: { title:{type:'string'}, reason:{type:'string'} } }
    },
    metaNotes: { type: 'string', description: 'Caveats about the data (what we measured vs missed), and what additional signals would raise confidence.' }
  }
};

const allRecs = validFindings.flatMap(f => f.recommendations.map(r => ({ perspective: f.perspective || 'unknown', ...r })));

const synth = await agent(
  `You are the synthesis judge. Below are recommendations from 6 specialists analyzing a pi session corpus. Your job: merge duplicates across specialists, rank by (impact × confidence / effort), separate the high-confidence top tier from speculative ones, and note what data would tighten the analysis. Be ruthless about deduplication — same idea phrased differently from two specialists = one merged rec with the higher evidence.\n\nEVIDENCE PACK (reference):\n${evidence}\n\nSPECIALIST RECOMMENDATIONS:\n${JSON.stringify(allRecs, null, 2)}\n\nReturn JSON matching the schema. Top tier: 8-12 items. Each must have a concrete action and an expected outcome (quantified if possible).`,
  { label: 'synthesizer', tier: 'big', schema: synthSchema }
);

return {
  ok: true,
  specialistCount: validFindings.length,
  rawRecCount: allRecs.length,
  topCount: synth?.topRecommendations?.length || 0,
  synth,
  specialists: validFindings
};
